class Getter:
 def __call__(self,owner): return 7
 def __getattribute__(self,name): raise ValueError("never")
p=property(Getter(),None,None,"explicit")
print(len(dir(p)),len(p.__dir__()))

class Getter:
 def __call__(self,owner): return 7
 @property
 def __isabstractmethod__(self): raise ValueError("never")
p=property(Getter(),None,None,"explicit")
print(len(dir(p)))

class Value:
 def __hash__(self): raise ValueError("never")
 def __bool__(self): raise ValueError("never")
 def __lt__(self,other): raise ValueError("never")
p=property()
p.__name__=Value()
p.__doc__=Value()
print(len(dir(p)))

def f(self): raise ValueError("never")
p=property(f)
print(len(dir(p)),p.fget is f)

class C:
 @property
 def field(self): return 7
p=C.field
print(p.__name__,"field" in dir(p),len(dir(p)),C().field)

class M(type): pass
class C(metaclass=M): field=property()
p=C.field
def read(cls,name): raise ValueError("never")
M.__getattribute__=read
print(len(dir(p)))
